import React, { useState, useEffect } from "react";

import styles from "./SmallCalendar.module.css";
import FullCalendar from "@fullcalendar/react";
import dayGridPlugin from "@fullcalendar/daygrid";
import interactionPlugin from "@fullcalendar/interaction"; // Add this import
/* import '@fullcalendar/daygrid/main.css';
import '@fullcalendar/interaction/main.css'; */
import styled from "@emotion/styled";

const StyleWrapper = styled.div`
  .fc td {
    background: #fff;
  }
  .fc-header-toolbar {
    height: 50px;
  }
  .fc .fc-scroller-liquid-absolute {
    position: relative;
  }

  .fc.fc-media-screen.fc-direction-ltr.fc-theme-standard {
    position: relative;
    height: 400px;
  }
  .fc-theme-standard td,
  .fc-theme-standard th {
    border: none !important;
  }
  .fc .fc-daygrid-day-top {
    justify-content: center;
  }
  .fc-toolbar-title {
    font-size: 20px;
  }
  .fc .fc-prev-button.fc-button-primary,
  .fc .fc-next-button.fc-button-primary {
    background-color: transparent;
    color: #000;
    border: none !important;
    box-shadow: none !important;
  }
  .fc-custom-today-button {
    background-color: #4169e1;
    border-radius: 20px;
    height: 40px;
    padding: 0px 30px;
    font-size: 30px;
    display: flex;
    justify-content: center;
    line-height: 40px;
    font-weight: 800;
  }
  .fc-view-harness {
    border-radius: 30px;
    /* overflow: hidden; */
  }
  .fc-scroller.fc-scroller-liquid-absolute {
    overflow: unset !important;
  }
  * {
    border: none !important;
  }
  .fc .fc-daygrid-day.fc-day-today {
    background-color: #fff;
  }
  .fc-daygrid-day-events {
    position: absolute !important;
    top: 0px;
    width: 100%;
    height: 42px !important;
  }
  .fc-daygrid-day-bg {
    z-index: 5;
  }
  .fc-bg-event {
    background-color: #4169e1;
    opacity: 1;
    border-radius: 30px;
    display: flex;
    justify-content: center;
    align-item: center;
  }
  .fc-bg-event .fc-event-title {
    font-style: unset;
    font-size: 1em;
    color: #fff;
    margin: 0px;
    position: absolute;
    top: 50%;
    transform: translatey(-50%);
  }
  .fc-daygrid-day-frame.fc-scrollgrid-sync-inner {
    min-height: 42.85px;
    height: 42.85px;
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
  }

  .fc-header-toolbar.fc-toolbar.fc-toolbar-ltr{
    margin-bottom: 10px;
  }

  @media (max-width: 1400px) {
    .fc-header-toolbar.fc-toolbar.fc-toolbar-ltr {
      font-size: 17px
    }
    .fc-col-header-cell-cushion {
      font-size: 18px;
    }

    .fc-daygrid-day-number {
      font-size: 20px;
    }

    .fc-daygrid-day-events {
      height: 30px !important;
    }

    .fc-toolbar-title {
      margin-left: 10px;
    }
  }
`;

function SmallCalendar({
  SmallCalendarRef,
  PlannerApi,
  SmallCalendarApi,
  viewDate,
  setViewDate,
  isAddPlanModal,
  width,
  setIsCalendarOpen,
}) {
  const [events, setEvents] = useState([]);

  useEffect(() => {
    setEvents([
      {
        start: viewDate,
        end: viewDate,
        allDay: true,
        display: "background",
        title: viewDate.getDate(),
      },
    ]);
    if (SmallCalendarApi) {
      SmallCalendarApi.gotoDate(viewDate);
    }
    if (PlannerApi && !isAddPlanModal) {
      PlannerApi.gotoDate(viewDate);
    }
  }, [viewDate]);

  const handleDateClick = (arg) => {
    setViewDate(arg.date);
    if (setIsCalendarOpen) {
      setIsCalendarOpen(false);
    }
  };

  const customHeader = {
    left: "title",
    center: "",
    right: "prev next",
  };

  const dayHeaderContentCallback = (args) => {
    return args.text.charAt(0);
  };

  return (
    <StyleWrapper style={{width: width}}>
      <div className={styles.SmallCalendar} style={{ width: width}}>
        <FullCalendar
          ref={SmallCalendarRef}
          plugins={[dayGridPlugin, interactionPlugin]}
          initialView="dayGridMonth"
          titleFormat={{ month: "long", year: "numeric" }}
          dayHeaderContent={dayHeaderContentCallback}
          headerToolbar={customHeader}
          dateClick={handleDateClick}
          select={handleDateClick}
          events={events}
        />
      </div>
    </StyleWrapper>
  );
}

export default SmallCalendar;
